-- Healthcare Encounter Dataset converted from the supplied markdown table
-- SQL Server syntax

IF DB_ID(N'Healthcare_Encounters') IS NULL
    CREATE DATABASE Healthcare_Encounters;
GO

USE Healthcare_Encounters;
GO

IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Healthcare')
    EXEC('CREATE SCHEMA Healthcare');
GO

IF OBJECT_ID(N'Healthcare.Healthcare_Encounters', N'U') IS NOT NULL
    DROP TABLE Healthcare.Healthcare_Encounters;
GO

CREATE TABLE Healthcare.Healthcare_Encounters (
    EncounterID INT IDENTITY(1,1) PRIMARY KEY,
    VisitDate DATE NOT NULL,
    PatientID VARCHAR(20) NOT NULL,
    PatientGender CHAR(1) NULL,
    PatientAge INT NULL,
    PatientSatScore INT NULL,
    FullName VARCHAR(100) NULL,a
    PatientRace VARCHAR(100) NULL,
    PatientAdminFlag BIT NULL,
    PatientWaitTime INT NULL,
    DepartmentReferral VARCHAR(100) NULL,
    Moment VARCHAR(10) NULL
);
GO

